def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==5:
                        seen.add(q); stack.append(q)
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if grid[y][x]==0: out[y][x]=2
            gaps=[x for x in range(c0,c1+1) if grid[r0][x]==0]
            if r0>0 and gaps:
                x=gaps[0]
                # Extend away from the top-edge 5 segment adjoining the gap.
                if x>c0 and x<c1 and grid[r0][x-1]==5 and grid[r0][x+1]==5:
                    for xx in range(0,x+1): out[r0-1][xx]=2
                else:
                    for xx in range(x,w): out[r0-1][xx]=2
    return out
